//! 🎯️ The selected full-body quote agrees with the original collection action and physical allocator.
use super::*;
use crate::RetainedCloneProgress;
fn run<T:RetireOwned>(value:T,body:usize){let mut owner=controlled::ControlledRetirement::new(value).unwrap_or_else(|_|panic!("original collection declares typed retirement"));for turn in 0..100000{if owner.terminal_is_empty(){return}let d=owner.selected_demand(body).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:body,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let(step,heap)=crate::observe_retirement_allocations(||owner.step(grant).unwrap());let p=step.progress();assert!(p.copied_bytes<=d.copy_bytes,"selected {d:?} performed {p:?}");assert_eq!(p.retained_capacity_bytes,heap.0);assert_eq!(p.released_bytes,heap.1);assert!(turn<99999);}}
#[test]fn original_plain_collection_body_quotes_cover_every_selected_element(){let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for body in law["bodyBytes"].as_array().unwrap(){let body=body.as_u64().unwrap()as usize;for count in law["counts"].as_array().unwrap(){let count=count.as_u64().unwrap()as usize;run(vec![37u8;count],body);run(vec![37u32;count],body);let mut list=crate::list::PagedList::<u32,{usize::MAX}>::default();for _ in 0..count{list.push(37);}run(list,body);}run([37u32;129],body);}}

#[test]fn original_close_selection_denial_preserves_the_same_collection_action(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let law=&law["selectedLoan"];let body=law["bodyBytes"].as_u64().unwrap()as usize;let mut value=Some(vec![37u8;law["count"].as_u64().unwrap()as usize]);let mut owner=semio_framework_value::retained_clone::RetainedCloneClose::default();let birth=owner.next_owner_demands::<Vec<u8>>(true,&None,body).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:birth.copy_bytes,maximum_capacity_bytes:birth.capacity_bytes,maximum_release_bytes:birth.release_bytes,maximum_depth:birth.depth};let(step,heap)=crate::observe_retirement_allocations(||owner.begin_granted(&mut value,grant).unwrap().unwrap());assert_eq!(step.progress().retained_capacity_bytes,heap.0);assert_eq!(step.progress().released_bytes,heap.1);assert!(value.is_none());let mut spans=0;
 for turn in 0..100000{if owner.is_empty(){assert!(spans>=2);return}let d=owner.demands(body).unwrap();let full=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};for axis in law["deniedCurrencies"].as_array().unwrap(){let mut denied=full;match axis.as_str().unwrap(){"items"=>denied.maximum_items=0,"copy" if d.copy_bytes>0=>denied.maximum_copy_bytes-=1,"capacity" if d.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,"release" if d.release_bytes>0=>denied.maximum_release_bytes-=1,"depth" if d.depth>0=>denied.maximum_depth-=1,_=>continue}let selection=owner.select(body).unwrap();assert_eq!(selection.demands(),d);let(step,heap)=crate::observe_retirement_allocations(||selection.step(denied).unwrap());assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!(heap,(0,0));assert_eq!(owner.demands(body).unwrap(),d);}
 let selection=owner.select(body).unwrap();let(step,heap)=crate::observe_retirement_allocations(||selection.step(full).unwrap());let p=step.progress();assert!(p.copied_bytes<=d.copy_bytes);assert_eq!(p.retained_capacity_bytes,heap.0);assert_eq!(p.released_bytes,heap.1);if p.copied_bytes==body{spans+=1;}assert!(turn<99999);}
}

fn selected_denials<T:crate::ErasedSnapshotRetirement>(owner:&mut T,body:usize)->bool{
 let d=owner.next_demand(body).unwrap();let full=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};for axis in 0..5{let mut denied=full;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>denied.maximum_release_bytes-=1,4 if d.depth>0=>denied.maximum_depth-=1,_=>continue}let loan=crate::select_retirement_cursor(owner,body).unwrap();let(step,heap)=crate::observe_retirement_allocations(||loan.step(denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(owner.next_demand(body).unwrap(),d);}
 let loan=crate::select_retirement_cursor(owner,body).unwrap();let(step,heap)=crate::observe_retirement_allocations(||loan.step(full).unwrap());let p=step.progress();assert!(p.copied_bytes<=d.copy_bytes);assert_eq!((p.retained_capacity_bytes,p.released_bytes),heap);p.copied_bytes==48
}
#[test]fn original_selected_typed_cursor_and_ticket_refuse_smaller_grants_for_the_same_48_byte_span(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let law=&law["selectedCursor"];let count=law["count"].as_u64().unwrap()as usize;let body=law["bodyBytes"].as_u64().unwrap()as usize;assert_eq!(law["expectedSpan"].as_u64().unwrap(),48);let mut typed=controlled::ControlledRetirement::new(vec![37u32;count]).unwrap_or_else(|_|panic!("plain original source declares retirement"));let mut seen=false;for index in 0..10000{if typed.terminal_is_empty(){break}let d=typed.select(body).unwrap().demands();assert_eq!(d,typed.selected_demand(body).unwrap());seen|=selected_denials(&mut typed,body);assert!(index<9999);}assert!(seen);
 let value=vec![37u32;count];let bytes=crate::owned_retirement_birth_bytes::<Vec<u32>>();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:bytes,maximum_release_bytes:0,maximum_depth:1};let(result,heap)=crate::observe_retirement_allocations(||crate::admit_owned_retirement(value,grant));let(owner,p)=result.unwrap_or_else(|_|panic!("original ticket birth must fit its quote"));assert_eq!((p.retained_capacity_bytes,p.released_bytes),heap);let mut ticket=Some(owner);let mut seen=false;for index in 0..10000{if ticket.is_none(){break}let d=crate::select_factory_ticket(&mut ticket,body).unwrap().demands();let full=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};if d.copy_bytes>0{let loan=crate::select_factory_ticket(&mut ticket,body).unwrap();let(step,heap)=crate::observe_retirement_allocations(||loan.step(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..full}).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));}let loan=crate::select_factory_ticket(&mut ticket,body).unwrap();let(step,heap)=crate::observe_retirement_allocations(||loan.step(full).unwrap());let p=step.progress();assert!(p.copied_bytes<=d.copy_bytes);assert_eq!((p.retained_capacity_bytes,p.released_bytes),heap);seen|=p.copied_bytes==48;assert!(index<9999);}assert!(seen);
}
